@sig trait RequestClassification_Api {
  def id: Art.BridgeId
  def access_request_Id : Art.PortId
  def request_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var request_facts: Docking_Access_Supervisor.RequestFacts = $

  def put_request_facts(value : Docking_Access_Supervisor.RequestFacts) : Unit = {
    Contract(
      Modifies(request_facts),
      Ensures(
        request_facts == value
      )
    )
    Spec {
      request_facts = value
    }

    Art.putValue(request_facts_Id, Docking_Access_Supervisor.RequestFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RequestClassification_Initialization_Api (
  val id: Art.BridgeId,
  val access_request_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends RequestClassification_Api

@datatype class RequestClassification_Operational_Api (
  val id: Art.BridgeId,
  val access_request_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends RequestClassification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var access_request: Docking_Access_Supervisor.AccessRequest.Type = $

  def get_access_request() : Option[Docking_Access_Supervisor.AccessRequest.Type] = {
    Contract(
      Ensures(
        Res == Some(access_request)
      )
    )
    val value : Option[Docking_Access_Supervisor.AccessRequest.Type] = Art.getValue(access_request_Id) match {
      case Some(Docking_Access_Supervisor.AccessRequest_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port access_request.  Expecting 'Docking_Access_Supervisor.AccessRequest_Payload' but received ${v}")
        None[Docking_Access_Supervisor.AccessRequest.Type]()
      case _ => None[Docking_Access_Supervisor.AccessRequest.Type]()
    }
    return value
  }
}
